-- Deities and Demigods: D&D pantheon divine stat blocks, batch E.
-- Source: Deities and Demigods (2002), Chapter 3, pp. 89-96.
-- Printed 3.0 statistics are preserved, with official 3.5 revision deltas recorded separately in mechanics JSON.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0',
        'Deities and Demigods (2002): divine ranks, pantheons, salient divine abilities, divine minions, domains, spells, monsters, prestige classes, and ascension.',NULL,1,0,NULL);

UPDATE dnd35_deities SET symbol='Laughing mask' WHERE source_id='dd-3.0' AND slug='olidammara' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Sun face' WHERE source_id='dd-3.0' AND slug='pelor' AND owner_user_id IS NULL;
