WITH desired(slug,name,page,description,mechanics) AS (VALUES
('dd-statblock-olidammara','Olidammara Divine Stat Block','89-90',
 'Olidammara the Laughing Rogue is a divine-rank-15 intermediate deity of rogues, music, revelry, wine, humor, and tricks.',
 '{"deitySlug":"olidammara","pantheon":"dnd","sourceEdition":"3.0","rankBand":"intermediate","divineRank":15,"titles":["The Laughing Rogue"],"symbol":"Laughing mask","homePlane":"Ysgard","alignment":"CN","classes":[{"class":"Rogue","level":20},{"class":"Bard","level":10},{"class":"Cleric","level":10}],"creature":{"type":"Outsider","subtypes":["Chaotic"],"size":"Medium","hitDice":"20d8+140 outsider + 20d6+140 rogue + 10d6+70 bard + 10d8+70 cleric","hitPoints":840,"initiative":"+24, always first","speed":{"land":60},"armorClass":{"total":84,"dexterity":20,"divine":15,"natural":28,"deflection":11},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"swiftstrike":"+81/+81/+76/+71/+66 melee, +5 chaotic keen speed rapier","damage":"1d6+12/12-20","spellTouch":{"melee":63,"ranged":76}},"saves":{"fort":54,"ref":69,"will":54,"intermediateDeityChecksAlways20":true},"abilities":{"str":24,"dex":50,"con":24,"int":30,"wis":24,"cha":33},"specialAttacks":{"sneakAttack":"+13d6","turnUndeadPerDay":14,"cripplingStrike":true},"specialQualities":{"printedDamageReduction":"50/+4","printedFireResistance":35,"spellResistance":47,"divineAura":{"radiusFeet":1500,"dc":35},"bardicKnowledgeBonus":20,"bardicMusicUsesPerDay":10,"bardicMusic":["countersong","fascinate","inspire competence","inspire courage","inspire greatness","suggestion"],"rogueFeatures":["evasion","improved evasion","opportunist","slippery mind","traps","uncanny dodge; cannot be flanked, +4 against traps"]},"salientDivineAbilities":["Alter Reality","Alter Size","Area Divine Shield","Avatar","Create Greater Object","Create Object","Divine Blast","Divine Celerity","Divine Dodge","Divine Recall (melodies)","Divine Rogue","Divine Shield","Divine Skill Focus (Bluff)","Divine Sneak Attack","Instant Move","Irresistible Performance (no calm effect)","Shift Form","Supreme Initiative"],"uniqueAbilities":{"shiftForm":{"forms":"any animal with a carapace","examples":["snail","turtle","dragon turtle"],"shellWithdrawal":{"actionsAllowed":false,"losesDefensiveDexterityBonus":true,"freeDivineShieldUses":"once per hour"}}},"domainPowers":{"chaosSpellsCasterLevelBonus":1,"luckRerollsPerDay":15},"spellLikeAbilities":{"casterLevel":25,"chaosCasterLevel":26,"saveDc":"35 + spell level"},"spellcasting":{"bardSpellsKnownPerDay":"3/6/6/5/2","bardBaseDc":"21 + spell level","clericSpellsPerDay":"6/7/7/6/5/4","clericBaseDc":"17 + spell level"},"possessions":{"swiftstrike":"+5 chaotic keen speed rapier; caster level 20; weight 3 lb."},"automaticActions":{"skills":["Craft (musical instrument)","Disable Device","Knowledge (arcana)","Knowledge (history)","Knowledge (local)","Open Lock","Profession (herbalist)","Profession (vintner)"],"freeActionDcMaximum":25,"pickPocketAsFreeAction":true,"maximumPerRound":10},"avatar":{"divineRank":7,"armorClass":68,"attacks":"Swiftstrike +73/+73/+68/+63/+58, 1d6+12/16-20","spellTouch":{"melee":56,"ranged":69},"damageReduction":"42/+4","fireResistance":27,"spellResistance":39,"divineAura":{"radiusFeet":700,"dc":27},"saves":{"fort":26,"ref":36,"will":26},"bluff":85,"otherSkillModifierReduction":8,"salientDivineAbilities":["Alter Size","Automatic Metamagic (quicken spell-like abilities)","Create Object","Divine Celerity","Divine Dodge","Divine Recall (melodies)","Divine Shield","Instant Move","Supreme Initiative"],"spellLikeCasterLevel":17,"spellLikeSaveDc":"27 + spell level"},"revision3_5":{"alignmentSubtypes":["chaotic"],"damageReduction":"25/epic","fireResistance":20,"rogueAdditionalTrapBonus":2,"notes":"Apply 3.5 rogue and bard class-feature/skill terminology while preserving source class levels and divine statistics; renamed skills such as Pick Pocket become Sleight of Hand."}}'),

('dd-statblock-pelor','Pelor Divine Stat Block','90-92',
 'Pelor the Shining One is a divine-rank-17 greater deity of the sun, light, strength, and healing.',
 '{"deitySlug":"pelor","pantheon":"dnd","sourceEdition":"3.0","rankBand":"greater","divineRank":17,"titles":["The Shining One"],"symbol":"Sun face","homePlane":"Elysium","alignment":"NG","classes":[{"class":"Cleric","level":20},{"class":"Druid","level":10},{"class":"Fighter","level":10}],"creature":{"type":"Outsider","subtypes":["Good"],"size":"Medium","hitDice":"20d8+180 outsider + 20d8+180 cleric + 10d8+90 druid + 10d10+90 fighter","hitPoints":1040,"initiative":11,"speed":{"land":60},"armorClass":{"total":73,"dexterity":7,"divine":17,"natural":30,"deflection":9},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"sunscepter":"+79/+74/+69/+64 melee, +5 disruption flaming heavy mace","damage":"1d8+42/19-20; greater-deity maximum damage 50","spellTouch":{"melee":69,"ranged":64},"greaterDeityAlways20OnAttacks":true,"greaterDeityMaximumDamage":true},"saves":{"fort":58,"ref":56,"will":64,"greaterDeityAlways20":true},"abilities":{"str":34,"dex":24,"con":28,"int":32,"wis":40,"cha":29},"specialAttacks":{"turnUndeadPerDay":24},"specialQualities":{"printedDamageReduction":"52/+4","printedFireImmunity":true,"fastHealing":37,"spellResistance":49,"divineAura":{"radiusMiles":19,"dc":36},"druidFeatures":["nature sense","resist nature''s lure","trackless step","venom immunity","wild shape Small/Medium/Large 4/day","woodland stride"]},"salientDivineAbilities":["Alter Reality","Alter Size","Area Divine Shield","Avatar","Call Creatures (eagles of all sorts)","Craft Artifact","Create Greater Object","Create Object","Divine Blast","Divine Creation","Divine Fast Healing","Divine Radiance","Divine Shield","Divine Storm","Divine Weapon Focus (heavy mace)","Divine Weapon Specialization (heavy mace)","Extra Domain (Strength)","Extra Energy Immunity (fire)","Gift of Life","Life and Death","Mass Divine Blast","Mass Life and Death"],"domainPowers":{"goodSpellsCasterLevelBonus":1,"healingSpellsCasterLevelBonus":1,"strengthUsesPerDay":17,"strengthEnhancementBonus":20,"greaterTurningUsesPerDay":17},"spellLikeAbilities":{"casterLevel":27,"goodAndHealingCasterLevel":28,"saveDc":"36 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/10/10/10/9/9/8/8/7/7","clericBaseDc":"25 + spell level","druidSpellsPerDay":"6/8/8/7/6/5","druidBaseDc":"25 + spell level"},"possessions":{"sunscepter":"+5 disruption flaming heavy mace; caster level 25; weight 8 lb."},"automaticActions":{"skills":["Craft (glassmaking)","Craft (metalworking)","Knowledge (arcana)","Knowledge (nature)","Knowledge (religion)","Knowledge (undead)","Profession (farmer)","Profession (herbalist)","Profession (sailor)"],"strengthRelatedSkillOrSimpleStrengthCheckAsFreeAction":true,"freeActionDcMaximum":30,"maximumPerRound":20},"avatar":{"divineRank":8,"armorClass":55,"attacks":"Sunscepter +66/+61/+56/+51, 1d8+25/19-20","spellTouch":{"melee":60,"ranged":55},"damageReduction":"43/+4","sourceFireResistance":"not separately listed; avatar retains Extra Energy Immunity (fire)","spellResistance":40,"divineAura":{"radiusFeet":800,"dc":27},"saves":{"fort":49,"ref":47,"will":55},"salientDivineAbilities":["Alter Size","Area Divine Shield","Divine Blast","Divine Fast Healing","Divine Radiance","Divine Shield","Extra Domain (Strength)","Extra Energy Immunity (fire)","Gift of Life","Life and Death"],"spellLikeCasterLevel":17,"spellLikeSaveDc":"27 + spell level"},"revision3_5":{"alignmentSubtypes":["good"],"damageReduction":"30/epic","rankBasedFireResistance":22,"explicitFireImmunityFromSalientAbility":true,"effectiveFireDefense":"immunity","druidChanges":"Apply 3.5 druid wild shape, wild empathy, animal companion and related terminology.","additionalOutsiderSkillPoints":true,"greaterDeityAlwaysMaximumRolls":true}}'),

('dd-statblock-st-cuthbert','St. Cuthbert Divine Stat Block','92-94',
 'St. Cuthbert of the Cudgel is a divine-rank-15 intermediate deity of retribution, common sense, wisdom, zeal, honesty, truth, and discipline.',
 '{"deitySlug":"st-cuthbert","pantheon":"dnd","sourceEdition":"3.0","rankBand":"intermediate","divineRank":15,"titles":["St. Cuthbert of the Cudgel"],"symbol":"Ruby-studded starburst","homePlane":"Arcadia","alignment":"LN","classes":[{"class":"Fighter","level":20},{"class":"Cleric","level":20}],"creature":{"type":"Outsider","subtypes":["Lawful"],"size":"Medium","hitDice":"20d8+160 outsider + 20d10+160 fighter + 20d8+160 cleric","hitPoints":1000,"initiative":11,"speed":{"land":60},"armorClass":{"total":69,"dexterity":7,"divine":15,"natural":28,"deflection":9},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"maceOfCuthbert":"+79/+74/+69/+64 melee, +5 disruption holy lawful heavy mace","damage":"1d8+43/19-20","spellTouch":{"melee":69,"ranged":62}},"saves":{"fort":37,"ref":34,"will":44,"intermediateDeityChecksAlways20":true,"sourceNote":"Printed saves are much lower than adjacent deities but are preserved exactly."},"abilities":{"str":38,"dex":24,"con":27,"int":24,"wis":45,"cha":29},"specialAttacks":{"turnUndeadPerDay":12},"specialQualities":{"printedDamageReduction":"50/+4","printedFireResistance":35,"fastHealing":32,"spellResistance":67,"divineAura":{"radiusFeet":1500,"dc":34}},"salientDivineAbilities":["Annihilating Strike","Alter Form","Alter Reality","Alter Size","Area Divine Shield","Divine Blessing (Wisdom)","Divine Fast Healing","Divine Shield","Avatar","Divine Blast","Divine Skill Focus (Sense Motive)","Divine Shield","Divine Storm","Divine Weapon Focus (heavy mace)","Divine Weapon Specialization (heavy mace)","Extra Domain (Destruction)","Increased Spell Resistance","Power of Truth"],"sourceAnomalies":{"duplicateSalientAbility":"Divine Shield is printed twice in the main salient-ability list and is retained verbatim in the source list."},"domainPowers":{"destructionSmiteUsesPerDay":15,"destructionSmiteAttackBonus":4,"destructionSmiteDamageBonus":20,"lawSpellsCasterLevelBonus":1,"protectiveWardUsesPerDay":15,"protectiveWardResistanceBonus":20,"strengthUsesPerDay":15,"strengthEnhancementBonus":20},"spellLikeAbilities":{"casterLevel":25,"lawCasterLevel":26,"saveDc":"34 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/11/10/10/10/10/8/8/8/8","clericBaseDc":"27 + spell level"},"possessions":{"maceOfCuthbert":"Major artifact; +5 disruption holy lawful heavy mace; searing light at will, caster level 20."},"automaticActions":{"skills":["Craft (armorsmithing)","Craft (metalworking)","Craft (weaponsmithing)","Knowledge (arcana)","Knowledge (history)","Knowledge (nobility and royalty)","Knowledge (religion)","Profession (lawyer)"],"freeActionDcMaximum":25,"maximumPerRound":10},"avatar":{"divineRank":7,"armorClass":53,"attacks":"Mace of Cuthbert +71/+66/+61/+56","spellTouch":{"melee":61,"ranged":54},"damageReduction":"42/+4","fireResistance":27,"spellResistance":59,"divineAura":{"radiusFeet":700,"dc":26},"saves":{"fort":29,"ref":26,"will":36},"senseMotive":84,"otherSkillModifierReduction":8,"salientDivineAbilities":["Alter Size","Divine Blast","Divine Fast Healing","Divine Shield","Divine Skill Focus (Sense Motive)","Divine Weapon Focus (heavy mace)","Extra Domain (Destruction)","Increased Spell Resistance","Power of Truth"],"spellLikeCasterLevel":17,"spellLikeSaveDc":"26 + spell level"},"revision3_5":{"alignmentSubtypes":["lawful"],"damageReduction":"25/epic","fireResistance":20,"additionalOutsiderSkillPoints":true,"notes":"Use revised fighter/cleric feat and skill terminology; preserve the source''s printed low saving throws as original data."}}'),

('dd-statblock-tiamat','Tiamat Divine Stat Block','94-96',
 'Tiamat, the Chromatic Dragon and Queen of Evil Dragons, is a divine-rank-10 lesser deity with five independently dangerous dragon heads.',
 '{"deitySlug":"tiamat","pantheon":"dnd","sourceEdition":"3.0","rankBand":"lesser","divineRank":10,"titles":["The Chromatic Dragon","Queen of the Evil Dragons"],"symbol":"Five-headed dragon","homePlane":"Baator","alignment":"LE","creature":{"type":"Dragon","size":"Colossal","hitDice":"49d12+588","hitPoints":906,"initiative":4,"speed":{"land":40,"fly":150,"flyManeuverability":"clumsy","swim":40},"armorClass":{"total":69,"size":-8,"divine":10,"natural":48,"deflection":9},"face":"40 ft. by 80 ft.","reachFeet":15},"attacks":{"bites":"5 at +70 melee, 4d6+19/19-20","wings":"2 at +65 melee, 2d8+9","sting":"+65 melee, 3d6+9 plus poison","spellTouch":{"melee":70,"ranged":51}},"saves":{"fort":48,"ref":36,"will":43},"abilities":{"str":49,"dex":10,"con":35,"int":28,"wis":25,"cha":29},"specialQualities":{"printedDamageReduction":"45/+4","printedFireImmunity":true,"spellResistance":42,"divineAura":{"radiusFeet":1000,"dc":29},"blindsightMiles":10,"scent":true,"darkvision":true,"waterBreathing":true,"teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"breathWeapons":{"save":"Reflex DC 56 half","white":{"shape":"70-ft cone","damage":"12d6 cold"},"black":{"shape":"140-ft line, 5 by 5 ft.","damage":"24d4 acid"},"green":{"shape":"70-ft cone","damage":"24d6 acid"},"blue":{"shape":"140-ft line, 5 by 5 ft.","damage":"24d8 electricity"},"red":{"shape":"70-ft cone","damage":"24d10 fire"}},"otherDragonAttacks":{"crush":{"reflexDc":56,"damage":"4d8+28 per round while pinned"},"tailSweep":{"diameterFeet":40,"maximumTargetSize":"Medium","damage":"2d8+28","reflexDc":56,"failure":"knocked down"},"multipleHeads":{"allFiveMayBiteAfterMoveOrCharge":true,"eachHeadMayInsteadUseBreathOrSpellLikeAbility":true,"oneSpellPerRoundCountsAsOneHeadStandardAction":true},"headSevering":{"singleSlashingHitDamageThreshold":185,"effect":"one head severed"},"soundImitation":{"willDc":43},"stingPoison":{"fortitudeDc":56,"initial":"3d6 temporary Constitution","secondaryAfter":"1 minute","secondary":"3d6 temporary Constitution"}},"salientDivineAbilities":["Alter Form","Alter Size","Alter Reality","Annihilating Strike","Area Divine Shield","Control Creatures (nongood dragons, or any dragon with Cha 12 or lower)","Divine Blast","Divine Shield","Extra Domain (Law)","Extra Sense Enhancement (blindsight)","Shapechange","Spell Immunity"],"domainPowers":{"evilSpellsCasterLevelBonus":1,"lawSpellsCasterLevelBonus":1,"smiteUsesPerDay":10,"smiteAttackBonus":20,"smiteDamageBonus":20},"spellLikeAbilities":{"casterLevel":20,"evilAndLawCasterLevel":21,"saveDc":"30 + spell level"},"additionalAbilities":{"corruptWater":{"usesPerDay":1,"volumeCubicFeet":10,"carriedLiquidWillDc":43},"charmReptiles":{"usesPerDay":3,"basis":"mass charm","willDc":27,"targets":"reptilian animals","communication":"as speak with animals"}},"spellcasting":{"clericSpellsPerDay":"6/8/8/8/7/7/6/6/5/5","clericBaseDc":"23 + spell level"},"uniqueAbilities":{"spellImmunity":"same unique salient divine ability concept as Bahamut; source lists Spell Immunity among Tiamat''s salient abilities"},"automaticActions":{"skills":["Knowledge (arcana)","Knowledge (dragonkind)","Knowledge (history)","Knowledge (the planes)","Knowledge (religion)"],"freeActionDcMaximum":20,"maximumPerRound":5},"avatar":{"divineRank":5,"armorClass":59,"attacks":{"bites":"5 at +65, 4d6+19/19-20","wings":"2 at +60, 2d8+9","sting":"+60, 3d6+9 plus poison"},"spellTouch":{"melee":65,"ranged":46},"damageReduction":"40/+4","printedSpellResistanceText":"397","normalizedLikelySpellResistance":37,"sourceAnomaly":"The extracted/printed avatar line reads SR 397; rank-scaled context and main SR 42 strongly indicate 37. Both values are retained.","divineAura":{"radiusFeet":50,"dc":24},"saves":{"fort":43,"ref":31,"will":38},"breathAndPoisonSaveDc":51,"salientDivineAbilities":["Alter Form","Alter Size","Divine Shield","Extra Domain (Law)","Shapechange","Spell Immunity"],"spellLikeCasterLevel":15,"spellLikeSaveDc":"25 + spell level"},"revision3_5":{"alignmentSubtypes":["evil","lawful"],"damageReduction":"20/epic","fireResistance":15,"spaceFeet":30,"reachFeet":20,"dragonDeityAdditionalSkillPointsFormula":"(6 + Int modifier) × 3","notes":"Official 3.5 update changes Colossal dragon space/reach and replaces rank-derived 3.0 fire immunity with resistance 5 + divine rank unless another explicit ability grants more."}}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT 'dd-rule-'||d.slug,'dd-3.0',d.page,d.slug,d.name,d.description,d.description,0,NULL,1,
       'deity-statblock','statblock',0,1,'dd-dnd-pantheon',NULL,
       '["deities-and-demigods","deity","statblock","d&d-pantheon"]',d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.source_id='dd-3.0' AND r.slug=d.slug AND r.owner_user_id IS NULL
);